/**
 * Marked.js Local Self-Contained Engine for Tottus Logistics Frontend
 * Reemplazo 100% local sin dependencias CDN para evitar bloqueos de Tracking Prevention en Edge/Chrome
 * y garantizar funcionamiento offline o abriendo via file:// o Live Server.
 */
(function(global) {
  'use strict';

  function escapeHtml(text) {
    if (!text) return '';
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseInline(text) {
    if (!text) return '';

    // 1. Inline code: `code`
    text = text.replace(/`([^`]+)`/g, function(_, code) {
      return '<code class="ios-inline-code">' + escapeHtml(code) + '</code>';
    });

    // 2. Bold: **text** or __text__
    text = text.replace(/(\*\*|__)(.*?)\1/g, '<strong>$2</strong>');

    // 3. Italic: *text* or _text_
    text = text.replace(/(\*|_)(.*?)\1/g, '<em>$2</em>');

    // 4. Links: [text](url)
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

    return text;
  }

  function parseMarkdown(md) {
    if (!md) return '';
    md = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    var lines = md.split('\n');
    var html = [];
    var inList = false;
    var listType = 'ul';
    var inTable = false;
    var tableAligns = [];
    var inBlockquote = false;
    var bqLines = [];

    function closeList() {
      if (inList) {
        html.push('</' + listType + '>');
        inList = false;
      }
    }

    function closeTable() {
      if (inTable) {
        html.push('</tbody></table></div>');
        inTable = false;
        tableAligns = [];
      }
    }

    function closeBlockquote() {
      if (inBlockquote) {
        html.push('<blockquote>' + parseInline(bqLines.join(' ')) + '</blockquote>');
        inBlockquote = false;
        bqLines = [];
      }
    }

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      var trimmed = line.trim();

      // Manejo de Blockquotes (> ...)
      if (trimmed.startsWith('>')) {
        closeList();
        closeTable();
        inBlockquote = true;
        bqLines.push(trimmed.replace(/^>\s*/, ''));
        continue;
      } else {
        closeBlockquote();
      }

      function isDelimiterRow(str) {
        var t = (str || '').trim();
        if (!t.startsWith('|') || !t.includes('-')) return false;
        var clean = t.replace(/^\|/, '').replace(/\|$/, '');
        var cols = clean.split('|');
        if (cols.length === 0) return false;
        return cols.every(function(col) {
          return /^[\s:]*-+[\s:]*$/.test(col);
        });
      }

      // Manejo de Tablas Markdown (| ... |)
      var isTableRow = trimmed.startsWith('|') && (trimmed.endsWith('|') || trimmed.includes('|'));
      if (isTableRow) {
        closeList();
        var cleanRow = trimmed.replace(/^\|/, '').replace(/\|$/, '');
        var cells = cleanRow.split('|').map(function(c) { return c.trim(); });

        if (!inTable) {
          // Es la fila de encabezado
          var nextLine = (i + 1 < lines.length) ? lines[i + 1].trim() : '';
          if (isDelimiterRow(nextLine)) {
            inTable = true;
            var cleanDelim = nextLine.replace(/^\|/, '').replace(/\|$/, '');
            tableAligns = cleanDelim.split('|').map(function(c) {
              var t = c.trim();
              var startColon = t.startsWith(':');
              var endColon = t.endsWith(':');
              if (startColon && endColon) return 'center';
              if (endColon) return 'right';
              if (startColon) return 'left';
              return 'left';
            });
            html.push('<div class="ios-table-scroll-container"><table><thead><tr>');
            cells.forEach(function(cell, idx) {
              var align = tableAligns[idx] || 'left';
              html.push('<th style="text-align:' + align + '">' + parseInline(cell) + '</th>');
            });
            html.push('</tr></thead><tbody>');
            i++; // Saltar la línea divisoria
            continue;
          }
        } else {
          // Fila de datos de la tabla
          html.push('<tr>');
          cells.forEach(function(cell, idx) {
            var align = tableAligns[idx] || 'left';
            html.push('<td style="text-align:' + align + '">' + parseInline(cell) + '</td>');
          });
          html.push('</tr>');
          continue;
        }
      } else {
        closeTable();
      }

      // Línea en blanco
      if (trimmed === '') {
        closeList();
        continue;
      }

      // Encabezados (#, ##, ###, ####)
      var headingMatch = trimmed.match(/^(#{1,6})\s+(.*)$/);
      if (headingMatch) {
        closeList();
        var level = headingMatch[1].length;
        var text = parseInline(headingMatch[2]);
        html.push('<h' + level + '>' + text + '</h' + level + '>');
        continue;
      }

      // Regla horizontal (--- o ***)
      if (/^(\-{3,}|\*{3,})$/.test(trimmed)) {
        closeList();
        html.push('<hr/>');
        continue;
      }

      // Elementos de lista no ordenada (- item o * item)
      var ulMatch = line.match(/^(\s*)([-*])\s+(.*)$/);
      if (ulMatch) {
        if (!inList || listType !== 'ul') {
          closeList();
          html.push('<ul>');
          inList = true;
          listType = 'ul';
        }
        html.push('<li>' + parseInline(ulMatch[3]) + '</li>');
        continue;
      }

      // Elementos de lista ordenada (1. item)
      var olMatch = line.match(/^(\s*)(\d+)\.\s+(.*)$/);
      if (olMatch) {
        if (!inList || listType !== 'ol') {
          closeList();
          html.push('<ol>');
          inList = true;
          listType = 'ol';
        }
        html.push('<li>' + parseInline(olMatch[3]) + '</li>');
        continue;
      }

      // Párrafos regulares o texto
      closeList();
      html.push('<p>' + parseInline(trimmed) + '</p>');
    }

    closeList();
    closeTable();
    closeBlockquote();

    return html.join('');
  }

  var markedObj = {
    parse: parseMarkdown,
    parseInline: parseInline
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = markedObj;
  } else {
    global.marked = markedObj;
  }
})(typeof window !== 'undefined' ? window : this);
